import {cardSVG} from './artwork.js';
import {cards,blank,acquire,points,match,parseCode} from './model.js';
const $=s=>document.querySelector(s), main=$('#main'), modal=$('#modal');
let state=blank(),storage=true;
try {const saved=JSON.parse(localStorage.getItem('lrd-v1'));if(saved&&Array.isArray(saved.owned)){state.owned=[...new Set(saved.owned.filter(id=>cards.some(c=>c.id===id)))];state.personal=cards.some(c=>c.id===saved.personal)?saved.personal:null;state.bonus=state.owned.length===6;}}catch{storage=false;}
let disposeScene=()=>{};
let screen='home',answers=[],question=0,stage='ready',timer,stream,scanTimer,kind='place';
function save(){try{localStorage.setItem('lrd-v1',JSON.stringify(state));}catch{storage=false;toast('Browser storage unavailable. Keep this tab open to preserve progress.');}update();}
function update(){$('#count').textContent=`${state.owned.length}/6`;$('#points').textContent=points(state);document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===screen));}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function card(c,back=false){return `<div class="playing-card ${back?'back':''}">${cardSVG(c,back)}</div>`;}
function stopCamera(){clearTimeout(scanTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;}
function nav(target){stopCamera();screen=target;render();window.scrollTo({top:0,behavior:'smooth'});}
function home(){return `<section class="hero persona-hero"><div class="hero-copy"><div class="issue-label"><span class="issue-square">✦</span> VOL. 01 / THE EVERYDAY ARCANA</div><h1><span class="headline-small">THE CITY HAS A STORY.</span><span class="headline-main">FIND<br>YOUR<br><em>PLACE.</em></span></h1><p class="intro">A personal reading. A local discovery. A connection waiting to happen. Meet Singapore through six cards — and find a little of yourself.</p><div class="actions"><button class="primary" id="begin">${state.personal?'VIEW MY PERSONAL CARD':'DRAW YOUR PERSONAL CARD'} <svg class="icon" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 16 16 4M5 4h11v11"/></svg></button><button class="secondary" data-go="scan">SCAN & COLLECT <span>⌗</span></button></div><p class="small-note">${state.personal?'Your story has begun. Keep discovering.':'Three questions. Six possibilities. One card that feels like you.'}</p><div class="coordinates">01°17′ N &nbsp; 103°51′ E <span>SINGAPORE</span></div></div><div class="hero-visual"><div class="scene-grid"></div><div class="scene-orbit orbit-one"></div><div class="scene-orbit orbit-two"></div><div class="scene-caption">SIX STORIES / ONE LITTLE RED DOT</div><div id="card-scene" class="card-scene" role="img" aria-label="Interactive 3D fan of six illustrated Singapore tarot cards"><div class="scene-fallback">${card(cards[2])}${card(cards[4])}${card(cards[0])}</div></div><div class="scene-detail"><span id="scene-word">Comfort</span><b id="scene-name">Hainanese chicken rice</b><small id="scene-hint">DRAG TO TURN · TAP A CARD TO EXPLORE</small></div><div class="scene-burst" aria-hidden="true">✳</div></div></section><div class="ticker" aria-hidden="true"><span>FOOD / RITUALS / ARTS</span><span>DISCOVER THE EVERYDAY ARCANA ✦</span><span>ONE CITY. MANY CONNECTIONS.</span></div><section class="deck-preview"><div class="section-top"><div><div class="eyebrow">THE NAN YANG COLLECTION</div><h2>Ordinary things.<br><em>Extraordinary meanings.</em></h2></div><p>Inspired by tropical colour, local craft<br>and the rhythms of life in Singapore.</p></div><div class="preview-strip" aria-label="Explore the six-card deck">${cards.map((c,i)=>`<button data-preview="${c.id}" class="preview-pick ${i===0?'active':''}" aria-pressed="${i===0}" aria-label="Preview ${c.name}"><span class="preview-number">0${i+1}</span>${card(c)}<span class="preview-label">${c.word}</span></button>`).join('')}</div></section><section class="journey"><div class="section-top"><h2>Your next move.</h2><p>Every card opens a new connection.</p></div><div class="steps"><div class="step"><span class="num">01</span><div><h3>MEET YOURSELF</h3><p>Answer three questions. Watch the whole deck shuffle, draw, then flip your personal card.</p></div></div><div class="step"><span class="num">02</span><div><h3>MEET THE CITY</h3><p>Scan a place QR. Read the cultural story. Collect a card inspired by what you discover.</p></div></div><div class="step"><span class="num">03</span><div><h3>MEET YOUR PEOPLE</h3><p>Scan a personal-card QR to receive a copy. Both people keep their cards. Complete six for a bonus.</p></div></div></div></section>`;}
const questions=[{title:'What are you drawn to today?',opts:[['A little comfort','Something simple and nourishing.'],['A fresh beginning','A small change, a new possibility.'],['A good conversation','Time to connect and listen.'],['An unexpected discovery','A different way to see things.']]},{title:'How do you approach a new place?',opts:[['Follow the flavours','Find a table and settle in.'],['Meet the people','Ask, listen, and share.'],['Notice the details','Look closely at what is made.'],['Let curiosity lead','Take the path you haven’t tried.']]},{title:'What would you like to make room for?',opts:[['Steadiness','More care in everyday moments.'],['Connection','A little more giving and receiving.'],['Patience','Time to create something meaningful.'],['Perspective','A story beyond the first impression.']]}];
function questionnaire(){const q=questions[question];return `<section class="flow"><button class="back-link" id="qback">← ${question?'Previous question':'Back to discover'}</button><div class="progress">${questions.map((_,i)=>`<span class="${i<=question?'done':''}"></span>`).join('')}</div><div class="eyebrow">A moment for yourself · ${question+1} of 3</div><h1>${q.title}</h1><p class="small-note">No right answers. Just what feels like you.</p><div class="options" role="group" aria-label="Choose one answer">${q.opts.map((o,i)=>`<button class="option ${answers[question]===i?'selected':''}" aria-pressed="${answers[question]===i}" data-answer="${i}">${o[0]}<span>${o[1]}</span></button>`).join('')}</div><button class="primary" id="next" ${answers[question]===undefined?'disabled':''}>${question===2?'Meet the deck':'Continue'} →</button><p class="small-note">Answers shape a creative reflection; this is not a prediction.</p></section>`;}
function draw(){const c=cards.find(c=>c.id===match(answers));if(stage==='revealed')return `<section class="flow"><div class="eyebrow">Your personal card</div><h1>${c.word}, in your own way.</h1>${card(c)}<p class="reading">${c.reading}</p><p class="small-note">A creative reflection inspired by your answers.</p><div class="actions"><button class="primary" data-go="collection">Explore my deck →</button><button class="secondary" id="share">Share my card</button></div></section>`;
return `<section class="flow"><div class="eyebrow">A small ritual of discovery</div><h1>${stage==='ready'?'Let the possibilities unfold.':stage==='shuffling'?'A little chance. A little you.':stage==='shuffled'?'Your card is waiting.':'Turn a new page.'}</h1><p class="small-note">${stage==='shuffling'?'All six cards are finding their place.':stage==='drawn'?'Tap your card to flip it and reveal your reading.':'Take a breath. There’s a story here for you.'}</p>${stage==='drawn'?`<div class="deck-stage"><button class="drawn" id="flip" aria-label="Flip your personal card">${card(c,true)}</button></div>`:`<div class="deck-stage ${stage==='shuffling'?'shuffling':''}">${cards.map((c,i)=>`<div style="--i:${i}">${card(c,true)}</div>`).join('')}</div>`}<button class="primary" id="draw-action" ${stage==='shuffling'?'disabled':''}>${stage==='ready'?'Shuffle the whole deck':stage==='shuffling'?'Shuffling…':stage==='shuffled'?'Draw a card':'Flip my card'} <span>✦</span></button></section>`;}
function collection(){return `<section><div class="collection-header"><div><div class="eyebrow">Your little discoveries</div><h1>Stories worth keeping.</h1><p class="intro">${state.owned.length} of 6 cards collected. Every new card adds 10 points.</p></div><button class="primary" data-go="scan">Scan & collect ↗</button></div><div class="meter" role="progressbar" aria-label="Collection progress" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${state.owned.length}"><span style="width:${state.owned.length/6*100}%"></span></div><p class="small-note">${state.bonus?'All six stories, one complete deck.':'Complete all six for a 50-point bonus.'} · Points are for this prototype.</p>${state.bonus?'<div class="banner">✦ The whole little deck! You earned the 50-point completion bonus.</div>':''}${!state.personal?'<button class="secondary" id="begin">Find my personal card →</button>':''}<div class="grid">${cards.map(c=>`<button class="collection-item ${state.owned.includes(c.id)?'':'locked'}" data-card="${c.id}" aria-label="${c.name}${state.owned.includes(c.id)?', collected':', not collected'}">${card(c)}<p>${state.personal===c.id?'✦ Your personal card':state.owned.includes(c.id)?'✓ Collected':'+ Waiting to be discovered'}</p></button>`).join('')}</div></section>`;}
function scan(){return `<section><div class="eyebrow">Places & people</div><h1>Find your next story.</h1><p class="intro">A place holds a story. A person holds a connection.<br>Scan a QR to add one to your deck.</p><div class="scan-layout"><div><div class="scanner" id="scanner"><span class="scanner-symbol">⌗</span><p>Point your camera at a card QR</p><button class="primary" id="camera">Open camera</button></div><p class="small-note">Camera scanning depends on browser support. You can also paste a card link or use a demo below.</p><label for="code">Card link or code</label><input id="code" placeholder="e.g. place:kaya-toast" autocomplete="off"><div id="scan-error" class="error" role="alert"></div><button class="secondary" id="code-go">Open card →</button></div><div><span class="badge">TRY THE PROTOTYPE</span><h2>Take a little detour.</h2><p class="small-note">These demo codes stand in for physical signs and another person’s card. No venue partnerships are implied.</p><div class="tabs" role="group" aria-label="Demo QR type"><button data-kind="place" class="${kind==='place'?'active':''}">Place QR</button><button data-kind="person" class="${kind==='person'?'active':''}">Person’s QR</button></div><div class="demo-list">${cards.map(c=>`<button data-demo="${c.id}">${c.name}<br><span class="small-note">${kind==='place'?c.place:'Receive a personal-card copy'} ↗</span></button>`).join('')}</div></div></div></section>`;}
function render(){disposeScene();disposeScene=()=>{};document.body.dataset.screen=screen;update();main.innerHTML=screen==='home'?home():screen==='questions'?questionnaire():screen==='draw'?draw():screen==='collection'?collection():scan();
main.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>nav(b.dataset.go));
const begin=$('#begin');if(begin)begin.onclick=()=>{if(state.personal)showCard(state.personal);else{answers=[];question=0;nav('questions');}};
main.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[question]=Number(b.dataset.answer);render();});
if($('#next'))$('#next').onclick=()=>{if(question<2){question++;render();}else{stage='ready';nav('draw');}};
if($('#qback'))$('#qback').onclick=()=>{if(question){question--;render();}else nav('home');};
if($('#draw-action'))$('#draw-action').onclick=()=>{if(stage==='ready'){stage='shuffling';render();setTimeout(()=>{stage='shuffled';if(screen==='draw')render();},3100);}else if(stage==='shuffled'){stage='drawn';render();}else if(stage==='drawn')reveal();};
if($('#flip'))$('#flip').onclick=reveal;
if($('#share'))$('#share').onclick=share;
main.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>showCard(b.dataset.card));
main.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{stopCamera();kind=b.dataset.kind;render();});
main.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>openCode(`${kind}:${b.dataset.demo}`));
if($('#code-go'))$('#code-go').onclick=()=>openCode($('#code').value);
if($('#code'))$('#code').onkeydown=e=>{if(e.key==='Enter')openCode(e.target.value);};
if($('#camera'))$('#camera').onclick=camera;
if(screen==='home'&&window.LittleRedScene)disposeScene=window.LittleRedScene.mount($('#card-scene'),{onSelect:id=>{const chosen=cards.find(c=>c.id===id);$('#scene-name').textContent=chosen.name;$('#scene-word').textContent=chosen.word;document.querySelectorAll('[data-preview]').forEach(b=>(b.classList.toggle('active',b.dataset.preview===id),b.setAttribute('aria-pressed',String(b.dataset.preview===id))));}});
main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{window.LittleRedScene?.select(b.dataset.preview);const chosen=cards.find(c=>c.id===b.dataset.preview);$('#scene-name').textContent=chosen.name;$('#scene-word').textContent=chosen.word;main.querySelectorAll('[data-preview]').forEach(t=>(t.classList.toggle('active',t===b),t.setAttribute('aria-pressed',String(t===b))));});
}
function collect(id){const result=acquire(state,id);state=result.state;save();toast(result.duplicate?'Already in your deck. No extra points.':result.award===60?'New card +10 · Complete deck bonus +50!':'New card collected · +10 points');return result;}
function reveal(){if(stage!=='drawn')return;state.personal=match(answers);collect(state.personal);stage='revealed';render();}
function openModal(html){stopCamera();$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal();}
function showCard(id){const c=cards.find(c=>c.id===id);openModal(`<div class="eyebrow">${state.personal===id?'Your personal card':c.theme}</div><h2>${c.name}</h2>${card(c)}<p>${c.story}</p><a class="source" href="${c.source}" target="_blank" rel="noopener">Cultural source ↗</a><p>${state.owned.includes(id)?c.reading:'Discover this card through a place or person’s QR.'}</p>${state.personal===id?'<button class="primary" id="share-modal">Share my card ↗</button>':''}`);if($('#share-modal'))$('#share-modal').onclick=share;}
function openCode(code){try{const {kind,id}=parseCode(code),c=cards.find(c=>c.id===id),owned=state.owned.includes(id);openModal(`<div class="eyebrow">${kind==='place'?'A place, a story':'A connection worth keeping'}</div><h2>${c.name}</h2>${card(c)}${kind==='person'?'<p>You’ll receive a copy of this person’s personal card. Their card stays with them, and yours stays with you.</p>':''}<p>${c.story}</p><a class="source" href="${c.source}" target="_blank" rel="noopener">Cultural source ↗</a><div class="actions"><button class="primary" id="collect">${owned?'Already collected':'Collect card'} ${owned?'✓':'+10'}</button></div><p class="small-note">${owned?'Duplicate cards earn no extra points.':kind==='person'?'Only the card type is shared, not their answers or reading history.':'Add this story to your six-card deck.'}</p>`);$('#collect').onclick=()=>{collect(id);modal.close();nav('collection');};}catch(e){if($('#scan-error'))$('#scan-error').textContent=e.message;else toast(e.message);}}
function share(){if(!state.personal)return;const code=`person:${state.personal}`,url=new URL(location.href);url.hash=new URLSearchParams({card:code}).toString();const qr=qrcode(0,'M');qr.addData(url.href);qr.make();openModal(`<div class="eyebrow">Pass on a little connection</div><h2>Your card is yours to keep.</h2><p>Let someone scan this QR to collect a copy of your ${cards.find(c=>c.id===state.personal).name} card.</p><div class="qr">${qr.createSvgTag({scalable:true})}</div><p class="small-note">Sharing code: <b>${code}</b><br>Both people keep their cards. A copy earns points only if it’s new.</p><button class="primary" id="copy">Copy card link ↗</button><p class="small-note">Hosted access rules still apply. Demo codes work within this prototype.</p>`);$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);toast('Card link copied');}catch{const input=document.createElement('input');input.value=url.href;$('#modal-body').append(input);input.select();toast('Select and copy the link below.');}};}
async function camera(){if(!('BarcodeDetector' in window)){ $('#scan-error').textContent='QR camera scanning isn’t supported in this browser. Paste a link or try a demo code.';return;}try{const detector=new BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(screen!=='scan'||modal.open){stopCamera();return;}$('#scanner').innerHTML='<video autoplay muted playsinline></video><button class="secondary" id="stop-camera">Stop camera</button>';const video=$('#scanner video');video.srcObject=stream;await video.play();$('#stop-camera').onclick=()=>{stopCamera();render();};const detect=async()=>{if(!stream)return;try{const codes=await detector.detect(video);if(codes.length){stopCamera();render();openCode(codes[0].rawValue);return;}}catch{}scanTimer=setTimeout(detect,300);};detect();}catch{stopCamera();$('#scan-error').textContent='Camera unavailable or permission declined. Paste a link or use a demo code.';}}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$('.brand').onclick=e=>{e.preventDefault();nav('home');};$('.close').onclick=()=>modal.close();modal.addEventListener('close',stopCamera);$('#reset').onclick=()=>{openModal('<h2>Start a fresh journey?</h2><p>This clears your cards and points from this browser.</p><div class="actions"><button class="primary" id="confirm-reset">Reset my deck</button><button class="secondary" id="cancel-reset">Keep my cards</button></div>');$('#cancel-reset').onclick=()=>modal.close();$('#confirm-reset').onclick=()=>{state=blank();save();modal.close();history.replaceState(null,'',location.pathname);nav('home');toast('Your deck is ready for a fresh start.');};};
function readHash(){const code=new URLSearchParams(location.hash.slice(1)).get('card');if(code){nav('scan');openCode(code);}}window.addEventListener('hashchange',readHash);window.addEventListener('pagehide',()=>{stopCamera();disposeScene();});render();readHash();if(!storage)toast('Storage unavailable. Progress is kept for this session.');
